/** The sum of the prices of the items, each price times its quantity. */
export function sumPrices(items) {
  return items.reduce((sum, item) => sum + item.price * item.qty, 0);
}

writes.src/cart.js:
import { sumPrices } from "./price.js";

/** The cart total, with the shipping cost added. */
export function cartTotal(items, shipping) {
  return sumPrices(items) + shipping;
}

